export default function ProvinceMapFilter() {
  const [active, setActive] = useState(null);
  const [tooltip, setTooltip] = useState(null);
  const [provinces, setProvinces] = useState(
    PROVINCES_BASE.map((p) => ({ ...p, listings: 0, animals: [] })),
  );
  const [hoveredProvince, setHoveredProvince] = useState(null);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

 const activeProv = provinces.find((p) => p.id === active);

function toggle(id) {
  setActive((prev) => (prev === id ? null : id));
  navigate(`/explore?province=${id}`);
}

  function handleBrowse() {
    if (activeProv) {
      navigate(`/marketplace?province=${activeProv.id}`);
    }
  }
  useEffect(() => {
    async function fetchProvinceCounts() {
      try {
        const snapshot = await getDocs(collection(db, "listings"));

        // Build a map: provinceId -> { count, animalSet }
        const counts = {};
        PROVINCES_BASE.forEach((p) => {
          counts[p.id] = { count: 0, animals: new Set() };
        });

        snapshot.docs.forEach((doc) => {
          const data = doc.data();
          if (data.status !== "active") return;

          const raw = (data.province || "").toLowerCase().trim();
          const provinceId = PROVINCE_MAP[raw];
          if (!provinceId) return;

          counts[provinceId].count += 1;

          // Pull animal/category name — adjust field name to match your schema
          if (data.categoryLabel || data.category) {
            counts[provinceId].animals.add(data.categoryLabel || data.category);
          }
        });

        setProvinces(
          PROVINCES_BASE.map((p) => ({
            ...p,
            listings: counts[p.id]?.count ?? 0,
            animals: [...(counts[p.id]?.animals ?? [])].slice(0, 3),
          })),
        );
      } catch (err) {
        console.error("Failed to fetch province data:", err);
      } finally {
        setLoading(false);
      }
    }

    fetchProvinceCounts();
  }, []);
  function handleMouseMove(e, prov) {
    if (!prov) return;
    const rect = e.currentTarget
      .closest("svg")
      .parentElement.getBoundingClientRect();
      const liveProv = provinces.find((p) => p.id === prov.id) || prov;
    setTooltip({
     prov: liveProv,
      x: e.clientX - rect.left + 14,
      y: e.clientY - rect.top - 12,
    });
  }

  return (
    <section className="pmf-section">
      <div className="section-inner">
        {/* Header */}
        <div className="pmf-header">
          <div>
            <p className="section-eyebrow">Coverage</p>
            <h2 className="section-title">Find livestock by province</h2>
            <p className="pmf-sub">
              Click any province to filter listings by location
            </p>
          </div>
          {active && (
            <button className="pmf-clear" onClick={() => setActive(null)}>
              Clear filter ✕
            </button>
          )}
        </div>

        <div className="pmf-layout">
          {/* ── MAP ── */}
          <div className="pmf-map-wrap">
            <svg
              viewBox="50 -80 980 1150"
              className="pmf-svg"
              xmlns="http://www.w3.org/2000/svg"
            >
              {/* Province shapes */}
              {Object.entries(PATHS).map(([id, d]) => {
                const prov = PROVINCES_BASE.find((p) => p.id === id);
                const isActive = active === id;
                return (
                  <g key={id}>
                    <path
                      d={d}
                      className={`pmf-path ${isActive ? "pmf-path--active" : "pmf-path--idle"}`}
                      onClick={() => toggle(id)}
                      onMouseMove={(e) => handleMouseMove(e, prov)}
                      onMouseEnter={() => setHoveredProvince(id)}
onMouseLeave={() => { setTooltip(null); setHoveredProvince(null); }}
                    />
                    <text
                      x={prov.cx}
                      y={prov.cy}
                      className={`pmf-label ${isActive ? "pmf-label--active" : ""}`}
                    >
                      {/* shorten long names for the map */}
                      {prov.name
                        .replace("Mashonaland ", "Mash. ")
                        .replace("Matabeleland ", "Mat. ")}
                    </text>
                  </g>
                );
              })}

              {/* Harare city rect */}
              {(() => {
                const isActive = active === "harare";
                const prov = PROVINCES_BASE.find((p) => p.id === "harare");
                return (
                  <g>
                    <rect
                      x="638"
                      y="262"
                      width="36"
                      height="56"
                      rx="5"
                      className={`pmf-path ${active === "harare" ? "pmf-path--active" : "pmf-path--idle"}`}
                      onClick={() => toggle("harare")}
                      onMouseMove={(e) => handleMouseMove(e, prov)}
                      onMouseLeave={() => setTooltip(null)}
                    />
                    <text
                      x="656"
                      y="292"
                      className={`pmf-label ${isActive ? "pmf-label--active" : ""}`}
                    >
                      HRE
                    </text>
                  </g>
                );
              })()}

              {/* Bulawayo city rect */}
              {(() => {
                const isActive = active === "bulawayo";
                const prov = PROVINCES_BASE.find((p) => p.id === "bulawayo");
                return (
                  <g>
                    <rect
                      x="456"
                      y="480"
                      width="46"
                      height="30"
                      rx="5"
                      className={`pmf-path ${active === "bulawayo" ? "pmf-path--active" : "pmf-path--idle"}`}
                      onClick={() => toggle("bulawayo")}
                      onMouseMove={(e) => handleMouseMove(e, prov)}
                      onMouseLeave={() => setTooltip(null)}
                    />
                    <text
                      x="479"
                      y="498"
                      className={`pmf-label ${isActive ? "pmf-label--active" : ""}`}
                    >
                      BYO
                    </text>
                  </g>
                );
              })()}
              {hoveredProvince && PROVINCE_TOWNS[hoveredProvince]?.map((town) => (
  <g key={town.name} className="pmf-town">
    <circle cx={town.x} cy={town.y} r="3" className="pmf-town-dot" />
    <text x={town.x} y={town.y - 7} className="pmf-town-label">
      {town.name}
    </text>
  </g>
))}
            </svg>

            {/* Tooltip */}
            {tooltip && (
              <div
                className="pmf-tooltip"
                style={{ left: tooltip.x, top: tooltip.y }}
              >
                <div className="pmf-tt-name">{tooltip.prov.name}</div>
                <div className="pmf-tt-row">
                  <span>Listings</span>
                  <span>{tooltip.prov.listings}</span>
                </div>
                <div className="pmf-tt-row">
                  <span>Top livestock</span>
                  <span>
                    {tooltip.prov.animals?.length > 0
                      ? `${tooltip.prov.animals[0]}${tooltip.prov.animals[1] ? `, ${tooltip.prov.animals[1]}` : ""}`
                      : tooltip.prov.listings > 0
                        ? "Various"
                        : "—"}
                  </span>
                </div>
              </div>
            )}
          </div>

          {/* ── PROVINCE LIST ── */}
          <div className="pmf-panel">
            <p className="pmf-panel-head">All provinces</p>
            {loading
              ? Array.from({ length: 10 }).map((_, i) => (
                  <div
                    key={i}
                    className="pmf-chip skeleton"
                    style={{ height: 36, marginBottom: 4 }}
                  />
                ))
              : provinces.map((p) => (
                  <button
                    key={p.id}
                    className={`pmf-chip ${active === p.id ? "pmf-chip--active" : ""}`}
                    onClick={() => toggle(p.id)}
                  >
                    <span className="pmf-chip-name">{p.name}</span>
                    <span className="pmf-chip-count">{p.listings}</span>
                  </button>
                ))}
          </div>
        </div>

        {/* ── RESULTS BAR ── */}
        {activeProv && (
          <div className="pmf-results">
            <div>
              <p className="pmf-results-label">
                Showing listings in {activeProv.name}
              </p>
              <p className="pmf-results-count">
                <strong>{activeProv.listings} listings</strong>
                {activeProv.animals?.length > 0 && (
                  <> · {activeProv.animals.join(", ")}</>
                )}
              </p>
            </div>
            <button className="pmf-browse-btn" onClick={handleBrowse}>
              Browse {activeProv.name} →
            </button>
          </div>
        )}
      </div>
    </section>
  );
}
